const m=[{id:"compassion-neff-definition",title:"Neff · Öz şefkat nedir? · Araştırma dosyası C11",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Çerçeve kendine anlayış göstermeyi, zorlanmanın ortak insan deneyimi olduğunu görmeyi ve zorluğu fark etmeyi birleştirir. Teselli eden ve koruyan şefkat, rahatlatmayı, korunmayı ve adım atmayı anlatan uygulayıcı ifadeleridir.",limitation:"Tanım sayfası; tek mekanizmanın veya tedavinin kanıtı değil. Özsaygı performansa bağlanabilir; bu bütün özsaygıyı tanımlamaz. Sıcak bir duygu hissetme şartı yok."},{id:"compassion-mindful-self-compassion-rct",title:"Neff ve Germer · 2013 · Bilinçli Farkındalık Temelli Öz Şefkat deneyi · C05",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"52 yetişkin sekiz haftalık programa veya bekleme listesine rastgele ayrıldı. Kontrollü son ölçümlerde birkaç sonuç programı destekledi. Oturumlar ve yoğun uygulama günü kayda değer uygulama gerektiriyordu.",limitation:"Geliştiricilerin yürüttüğü küçük bir program deneyi. Ara veya mektup sınaması değil. Bir yıllık izlemde 15 katılımcı yanıt verdi; eşzamanlı kontrol yoktu. Bütün katılımcılar için kontrollü faydaların korunduğunu gösteremez."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · Şefkat odaklı terapi · C07",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Klinik ve kuramsal derleme, tehdit, başarma isteği ve bağ kurarak yatışmayı işlevsel bir çerçeve olarak anlatır. Şefkat odaklı uygulamalara yer verir.",limitation:"Üç anatomik düğme veya tek başına nefes verme ya da canlandırmanın kanıtı değil. Gerçek güvenlik, imkânlar ve maddi ihtiyaçlar önem taşıyabilir. Güvende hissetme uygulamaları rahatsız edebilir."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig ve Mashek · 2007 · Ahlaki duygular · C08",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"Bütün benliğe yönelen utanç, sıklıkla geri çekilme veya savunmaya geçmeyle ilişkilidir. Davranışa odaklanan suçluluk, empati ve telafiyle ilişkili olabilir.",limitation:"Çoğunlukla gözleme dayanan anlatı derlemesi. Bunlar eğilimdir, kesin yasa değil. Aşırı suçluluk zarar verebilir. Zarar gördükten sonra utanç duymak, yanlış yaptığını veya özür borcun olduğunu göstermez."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Utançla baş etme kuramı · C09",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"215 kadınla görüşmeler, utancı tanımayı, beklentileri gerçeklikle karşılaştırmayı, güvenli bağ kurmayı ve utancı adlandırmayı içeren çerçeveyi geliştirdi.",limitation:"Nitel kuram geliştirme çalışması. Dört adımlı tedavinin kontrollü sınaması değil. Paylaşım isteğe bağlı; yalnızca güvenli ve dinlemeye istekli biriyle. Bedene odaklanma veya travmayı hatırlama zorunluluğu yok."},{id:"compassion-improvement-motivation",title:"Breines ve Chen · 2012 · Gelişme isteği · C06",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Dört deney kısa vadeli gelişme isteği buldu. Testte başarısızlık sonrası şefkat grubundakiler, hatırlatma almayanlardan daha uzun çalıştı: 306,5 saniyeye karşı 203,2 saniye.",limitation:"İkinci test puanlarında istatistiksel olarak anlamlı artış bulunmadı. Özsaygı grubuyla karşılaştırma kesin sonuca varmadı. Telafi isteği gerçek telafi değildir. Kalıcı değişim veya bağımsız, önceden kaydedilmiş tekrar doğrulanmadı."},{id:"compassion-journal-guidance",title:"Neff · Öz şefkat günlüğü · C18",url:"https://self-compassion.org/exercises/exercise-6-self-compassion-journal/",type:"technique",finding:"Geliştiricinin rehberi, bir zorluğu fark etmeyi, başkalarının da benzer şeyler yaşadığını görmeyi ve kendine anlayışlı sözler yazmayı ister. Bir hafta veya daha uzun süre her gün yazmayı önerir.",limitation:"Tek başına etki kanıtı veya sınanmış ODA biçimi değil. Daha erken saat veya kısa düşünme uyarlamadır. Yazmak sıkıntıyı artırıyorsa atlanabilir ya da bırakılabilir."},{id:"compassion-break-guidance",title:"Neff · Öz şefkat molası · C16",url:"https://self-compassion.org/exercises/exercise-2-self-compassion-break/",type:"technique",finding:"Geliştiricinin yöntemi, incinmeyi fark etmeyi, ortak insan deneyimini görmeyi ve anlayışlı sözler veya dilek sunmayı içerir. Özgün rehberde destekleyici dokunuş vardır.",limitation:"Tek başına etki sınaması veya kanıtlanmış iki dakikalık süre değil. ODA dokunmayı isteğe bağlı tutar; hafif örnekler, normal nefes, dışarıya dikkat ve durma seçenekleri sunar."},{id:"compassion-touch-trial",title:"Dreisoerner ve diğerleri · 2021 · Kendine dokunma deneyi · C14",url:"https://doi.org/10.1016/j.cpnec.2021.100091",type:"research",finding:"Son örneklemde 159 sağlıklı genç yetişkin vardı. Kendine dokunmak, laboratuvar stresine kortizol yanıtlarını değiştirdi. Bildirilen stres ve kalp hızında fark bulunmadı.",limitation:"Eksik verileri analiz etme biçimi değişen, önceden kaydedilmiş tek deney. Oksitosin ölçülmedi; duygusal rahatlama garantisi yok, klinik etkinlik gösterilmedi. Normal nefes ve dokunmama seçenekleri ODA uyarlamalarıdır."},{id:"compassion-kindness-review",title:"Zeng ve diğerleri · 2015 · İyi dilek meditasyonu derlemesi · C10",url:"https://doi.org/10.3389/fpsyg.2015.01693",type:"research",finding:"1.759 katılımcılı veriye dayanan 24 çalışmada farklı tasarımlar vardı. İlgili alt gruplarda iyi dilek meditasyonu tahmini 0,424, şefkat meditasyonu tahmini 0,286’ydı. Alt gruplar arasında istatistiksel olarak anlamlı fark bulunmadı.",limitation:"24 rastgele atamalı deney veya kazanan uygulama kanıtı değil. Yöntemler farklı, çalışmalar erken; kontroller sıklıkla bekleme listesiydi. ODA’nın yatışma alıştırmalarının etkisini tahmin etmez."},{id:"compassion-practice-safety",title:"Neff · Öz şefkat uygulama rehberi · C12",url:"https://self-compassion.org/self-compassion-practices/",type:"guidance",finding:"Geliştiricinin rehberi, anlayışlı bir niyet ile hoş duygular hissetmeyi birbirinden ayırır. Uygulama yoğun sıkıntı verirse geri çekilmeyi önerir.",limitation:"Uygulayıcı önerisi. Yeni tanı veya kanıtlanmış fizyolojik “backdraft”, yani ters tepme mekanizması değil. Rahatsız eden iç odağın yerine dışarıya dikkat, gündelik destek veya durmak seçilebilir."},{id:"compassion-letter-guidance",title:"Neff · Arkadaşın ağzından mektup rehberi · C17",url:"https://self-compassion.org/exercises/exercise-3-exploring-self-compassion-through-writing/",type:"technique",finding:"Geliştiricinin rehberi, ilgili bir arkadaşın bakışını, değişim için anlayışlı önerileri ve mektubu daha sonra okumak üzere kenara koymayı anlatır.",limitation:"Tek başına etki sınaması veya doğrulanmış on beş dakikalık süre değil. Program deneyi mektubu ayrı sınamadı. Acı hikâyesi, sıcak duygu, suçluluk veya paylaşım şartı yok."}],s=[{schemaVersion:2,revision:2,id:"compassion-1",courseId:"compassion",locale:"tr",title:"Yine aksadı mı? Hatayı düzelt, kendine hakaret etme.",goal:"Başa çıkabileceğin bir aksama seç. Adilce anlat; işe yarayan bir telafi, iş veya destek adımı at.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"İçindeki eleştirmen çıtayı yüksek tuttuğunu söylüyor. Son hakareti sana hangi yararlı işi yaptırdı?",reason:{id:"compassion-1-reason",label:"Kendini eleştirmek hangi yararlı adımı geciktirdi?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek hatayı düzeltmek","Yararlı işe geri dönmek","Daha erken destek istemek"]},why:{id:"compassion-1-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-1-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kendine anlayış göstermekle çaba harcamak bir arada olabilir. Testte başarısızlıktan sonra yapılan bir deneyde, şefkatli düşünmeye yönlendirilen öğrenciler hatırlatma almayanlardan daha uzun çalıştı. Sonraki sınav puanlarında istatistiksel olarak anlamlı artış bulunmadı. Bu kısa vadeli çabayla ilgili; sonuç garantisi değil. Daha çok çalışmakla daha iyi puan almak ayrı şeyler.","Kurs boyunca gündelik bir aksamayla ilerle. Ne olduğunu açıkça söyle, hakareti çıkar: “Süreyi az hesapladım.” “Ben işe yaramam” değil. Sonra düzelt, işe dön veya destek iste. Verdiğin zararda telafiyi, gördüğün zararda korunmayı düşün. Daha şefkatli hissetmen isteğe bağlı. Yaptığın iş, başlama anı ve sonuç aynı denemenin parçaları olacak."],example:{title:"Kerem’in yeni teslim tarihi",text:"Saat 17.00’de Kerem rapor için az süre hesapladığını fark ediyor. “Dikkatsiz aptal” demek yerine neyi kaçırdığını söylüyor. Masasından gerçekçi yeni tarihi gönderiyor; sonraki tahminine ek süre koyuyor. Yöneticisi hayal kırıklığı yaşıyor. Kerem güncellemeyi ve düzeltmeyi kaydediyor. Gecikmeye hâlâ üzülüyor, ama telafi başladı. Kendini daha iyi hissetmeyi beklemeden diğerlerine gereken bilgiyi vermiş oldu."}},move:{invitation:"Başa çıkabileceğin bir aksama seç. Ne olduğunu açıkça söyle; yeni bir hakaret yerine işe yarayan bir adım at.",instructions:["Olanı belirt. Değerin hakkında hüküm verme.","Uygun bir telafi, iş veya destek adımı at."],prompts:[],suggestions:{action:["Gerçekçi yeni teslim tarihini gönder","İşteki gerçek bir hatayı düzelt","İşe yarayan bir destek iste"],minimum:["Olanı anlatan bir güncelleme cümlesi gönder","Gerçek bir hatayı düzelt","Tek bir destek ihtiyacını belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Az hesapladığım süreyi kontrol edince","Sonraki başa çıkabileceğim aksamada"],place:["Çalışma masamda","Güvenli bir mesajlaşmada"],minutes:[3,2,5],fallback:["İşin süresini hesaplamak için yardım iste","Destek için daha güvenli yol seç"],observation:["Yaptığım güncelleme veya düzeltme","Nasıl bir yanıt geldiği"]},suggested:{action:"Gerçekçi yeni teslim tarihini gönder",minimum:"Olanı anlatan bir güncelleme cümlesi gönder",minutes:3,cueHint:"Az hesapladığım süreyi kontrol edince",placeHint:"Çalışma masamda",obstacleHint:"Aksamayla ilgilenmek yerine kendime hakaret ediyorum.",fallbackHint:"İşin süresini hesaplamak için yardım iste",observationHint:"Yaptığım güncelleme veya düzeltme"},stopRule:"Gündelik bir aksama seç. Sıkıntı hissedersen dur. Sıkıntı sürüyorsa veya yoğun geliyorsa destek ara.",accessibleAlternative:"Nötr sözler kullanabilir, alıştığın iletişim yolunu seçebilir veya yardım alabilirsin. Kendine sıcak duygular beslemen, bedenine odaklanman veya yaşadıklarını paylaşman gerekmiyor."},result:{question:"Seçtiğin yararlı adımı attın mı?",observationPrompt:"Neyi düzelttin, ne istedin veya gerçekte ne yaptın?"},judgment:{primary:{id:"compassion-1-missed-estimate",scenario:"Kerem işe gereken süreyi az hesapladığı için teslim tarihini kaçırdı. Şimdi gerçekçi bir tarih verebilir ve süre hesabını değiştirebilir.",question:"Hangi yanıt anlayışı sorumlulukla birleştirir?",bestOptionId:"update-and-adjust",options:[{id:"update-and-adjust",text:"Süre hesabındaki hatayı hakaretsiz anlatsın, gerçekçi tarihi göndersin ve sıradaki işi hesaplarken kullandığı adımı değiştirsin.",feedback:"Bu seçim gecikmenin gerçek etkisini görünür tutup telafiyi başlatıyor. Kerem aksamaya üzülürken yararlı bilgi verebilir ve planını geliştirebilir. Kendine anlayış göstermek gecikmeyi mazur saymasını gerektirmez."},{id:"wait-for-shame",text:"Akşamı dinlenmeye ayırsın; utancı konuşabileceği kadar hafiflediğinde ekibe göndereceği güncellemeyi o zaman hazırlamaya başlasın.",feedback:"Dinlenmek uygun olabilir, ama güncelleme şimdi mümkün ve gerekli. Utancın azalmasını beklemek diğerlerini bilgisiz bırakır. Önce gerçekçi tarihi gönder, sonra ihtiyacın olan dinlenmeyi seç."},{id:"explain-regret",text:"Gecikme yüzünden ne kadar kötü hissettiğini anlatsın; iş netleşince yeni tarihi göndereceğine dair söz versin.",feedback:"Dürüst pişmanlık özürde yer alabilir. Ama Kerem’in zaten bildiği şeyin yerine geçmez. Kendini ne kadar cezalandırdığını anlatmak yerine gerçekçi tarihi ver ve süre hesabıyla ilgilen."}]}},carry:{takeaway:"Beklentini değiştirmeden ne olduğunu açıkça söyle. Kendine gösterdiğin özeni sıradaki yararlı işle ortaya koy.",followUp:{questionId:"compassion-1-return",question:"Kendine haksızlık etmeden konuşmak yararlı bir adıma yardımcı oldu mu, sözde mi kaldı, destek veya ara ihtiyacını mı gösterdi?",observationPrompt:"Gerçek güncellemeyi, düzeltmeyi veya talebi belirt; mümkün olmadıysa bunu da yaz.",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Daha çok çaba, daha iyi puan demek değildi",paragraphs:["Breines ve Chen, öz şefkat ve gelişme isteği hakkında dört deney yaptı. Testte başarısızlıktan sonra şefkat grubundakiler ortalama 306,5 saniye çalıştı. Hatırlatma almayan grupta bu süre 203,2 saniyeydi. Özsaygıyı destekleyen sözler alan grupla karşılaştırma kesin sonuca varmadı. İkinci test puanlarında da istatistiksel olarak anlamlı fark bulunmadı. Yanlış davranış deneyinde telafi isteği ölçüldü, tamamlanmış telafi değil. [C06: compassion-improvement-motivation] Çalışma süresini puana veya bir şeyi istemeyi yapmış olmaya çevirmemek gerekir. Her sonuç kendi ölçtüğü şeyle sınırlı kalır.","Bu kısa deneyler çoğunlukla öğrencilerleydi; makalede çevrim içi yetişkin örneklemi de vardı. Kalıcı değişimi veya bu dersin sözlerinin etkisini belirlemiyorlar. Anlayış çabaya eşlik edebilir, ama kendine haksızlık etmeden kurduğun bir cümle motivasyonu, performansı veya telafiyi garanti etmez. Ders, sonrasına gerçek bir adım ekliyor; bu ODA uyarlaması. O davranışı doğrudan bildir. Yardım etmeyen yanıt, yarım kalan düzeltme veya fırsat olmaması da kayda girebilir. Yeni tarih göndermek güncelleme yaptığının kanıtıdır. Geciken işin bittiğinin kanıtı değildir. Sonraki kararında bu farkı koru; kaydı olduğundan büyük gösterme."]},{heading:"Aynı aksama için işe yarayan bir yol",paragraphs:["Neff öz şefkati, kendine anlayış göstermek, zorlanmanın ortak insan deneyimi olduğunu görmek ve zorluğu fark etmek olarak anlatır. Hatayı unutmak veya zarar veren davranışı onaylamak gerekmez. Bu bir tanım ve uygulayıcı çerçevesidir. Üç ayrı kanıtlanmış mekanizma değildir. [C11: compassion-neff-definition] Burada kendine nötr biçimde saygı duyman yeterli: ne olduğunu söyle, onunla ilgilenmene yardım edecek adımı seç. Sıcak sözler yapay geliyorsa zorlamana gerek yok. Olanı küçültmeden, kendini de aşağılamadan anlatabilirsin.","Ele aldığın aksama veya tekrarlayan durum aynı kalsın ve başa çıkabileceğin düzeyde olsun. Sonraki dersler yaptığın iş için gereken desteği düzenler; iyi hissetme yükümlülüğü eklemez. Gerçekten hata yaptığın yerde düzeltme gerekir. Zarar gördüğün veya işin imkânlarını aştığı yerde destek ya da korunma gerekebilir. Alıştırmaya uysun diye özür uydurma. Kaydında denenmiş telafi, dönülen iş, iletilen destek talebi veya uygun ara olabilir. Bir davranışı yaptığını bildirmeden plan, plan olarak kalır. Karşı tarafın yanıtını ise sen belirleyemezsin. Kaydettiğin adımı o yanıtın iyi olmasına bağlaman gerekmiyor."]}],sourceIds:["compassion-improvement-motivation","compassion-neff-definition"]}},{schemaVersion:2,revision:2,id:"compassion-2",courseId:"compassion",locale:"tr",title:"Herkes zorlanır. Senin hayal kırıklığın da yer bulsun.",goal:"Aynı aksamaya verdiğin yanıtta eksik kalan desteği ekle. Sonra işe yarayan en küçük adımını yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"“Herkes hata yapar” kendini susturmanın başka yolu olabiliyor. Yanıtında hangi ihtiyaç eksik kaldı?",reason:{id:"compassion-2-reason",label:"Hayal kırıklığını geçiştirince neyle ilgilenemiyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["İnciten şeyi kabul etmek","“Yalnız bende sorun var” demeyi bırakmak","Kendimi susturmadan işe geri dönmek"]},why:{id:"compassion-2-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-2-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Neff’in çerçevesi zorluğu fark etmeyi, başkalarının da zorlandığını görmeyi ve kendine yardımcı olacak bir yanıt vermeyi birleştirir. “Herkes başarısız olur, büyütmeyi bırak” ortak deneyimi görür ama acıyı geçiştirir. Acıyı söyleyip destek sunmamak da başka bir kısmı eksik bırakır. Üçüne bakmak, kendi yanıtında ne olmadığını görmene yardım edebilir.","Aynı aksamada eksik kalan kısım için nötr bir cümle ekle. “Hayal kırıklığı yaşıyorum; bir soruya yeniden bakabilirim” yeterli olabilir. Özsaygı performansa bağlanabilir. Bu, bütün özsaygının tanımı değildir. Bu uygulamada kimseyle yarışman gerekmiyor. Sonra mevcut yararlı adımının en küçük kısmını yap veya uygun destek seç. Daha iyi hissetmek zorunda değilsin."],example:{title:"İrem’in yeniden baktığı soru",text:"Akşam yemeğinden sonra İrem, dün seçtiği sınav hatasına bakıyor. “Herkes başarısız olur” diyerek hayal kırıklığını kabul etmekten kaçınmış. Mutfaktaki masasında “Bu canımı acıtıyor; bir soruyu anlamak için kendime yardım edebilirim” ekliyor. İki dakika soruyu yeniden inceliyor. Sonuçtan hâlâ memnun değil, daha fazla çalışma gerekiyor. Kendine güven puanı yerine, hangi soruya baktığını kaydediyor. Bir cümleyle duygusunu yok ettiğini söylemiyor."}},move:{invitation:"Son yanıtında eksik kalan desteği ekle. Aynı yararlı işi yaparken onu kullan.",instructions:["Zorluğu abartmadan veya geçiştirmeden kabul et.","Mevcut yararlı işinin en küçük kısmını yap veya uygun destek seç."],prompts:[],suggestions:{action:["Yanlış çözdüğüm bir deneme sorusuna yeniden bak","Seçtiğim işteki hatayı düzelt","Planladığım destek talebini gönder"],minimum:["Bir deneme sorusunun çözümünü çalış","Gerçek bir hatayı düzelt","Bir destek talebi ilet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Akşam yemeği sonrası değerlendirme zamanımda","Aynı aksamanın başladığı anda"],place:["Mutfaktaki masamda","Güvenli çalışma yerimde"],minutes:[2,1,5],fallback:["Soruyu anlamak için yardım iste","Tarafsız bir cümle kur ve adımı küçült"],observation:["Kullandığım destek cümlesi ve yaptığım iş","Hâlâ nerede yardım gerektiği"]},suggested:{action:"Yanlış çözdüğüm bir deneme sorusuna yeniden bak",minimum:"Bir deneme sorusunun çözümünü çalış",minutes:2,cueHint:"Akşam yemeği sonrası değerlendirme zamanımda",placeHint:"Mutfaktaki masamda",obstacleHint:"Yapacağım işe destek olmak yerine zorluğu geçiştiriyorum.",fallbackHint:"Soruyu anlamak için yardım iste",observationHint:"Kullandığım destek cümlesi ve yaptığım iş"},stopRule:"Acı veren hatırlamayı atla. Uygulama yoğun sıkıntı verirse destek ara.",accessibleAlternative:"Nötr sözleri içinden söyle, yaz, işaret dili kullan veya yardım iste. Sıcak duygu veya kıyas gerekmiyor."},result:{question:"Eklediğin destekle işe yarayan en küçük adımını gerçekten yaptın mı?",observationPrompt:"Hangi desteği ekledin ve o anda gerçekte ne yaptın?"},judgment:{primary:{id:"compassion-2-dismissed-disappointment",scenario:"İrem sınavdaki hayal kırıklığını “Herkes başarısız olur” diye geçiştiriyor. Dinlenmiş durumda; boş beş dakikası ve işaretlenmiş hazır bir sorusu var. Akşam vardiyasından sonra çalışma zamanı kalmayacak.",question:"Hangi yanıt elindeki çalışma fırsatını destekler?",bestOptionId:"acknowledge-and-review",options:[{id:"break-and-review-later",text:"Hayal kırıklığını kabul edip şimdi kısa bir çalışma arası versin, hazır soruyu vardiya sonrasına bıraksın.",feedback:"Ara, gerektiğinde gücünü koruyabilir. Burada İrem dinlenmiş ve sonrasında çalışma zamanı yok. Hazır soruyu şimdi kullan. Vardiyanın etrafında dinlenmesini ayrıca planlayabilir; bu duygu çalışmaya engel olmak zorunda değil."},{id:"organize-review-topics",text:"Hayal kırıklığını kabul etsin; beş dakikayı daha çok çalışması gereken konuların genel listesini hazırlamaya ayırsın.",feedback:"Öncelikler belirsizse genel liste yararlıdır. Bu soru zaten seçilmiş ve hazır. Şimdi sorunun çözümünü incele; zor kalan kısmı sonra hazırlayacağı genel liste için yol gösterici olarak kullan."},{id:"acknowledge-and-review",text:"Hayal kırıklığını kabul etsin, başkalarının da zorlandığını görsün; hazır soruyu incelerken kendine haksızlık etmeden konuşsun.",feedback:"Ortak deneyim İrem’in hayal kırıklığını silmez. Bu yanıt, duyguyu gözden kaçırmadan yararlı bir işe destek veriyor. Kendini başkalarıyla kıyaslaması veya hemen rahatlaması gerekmiyor; baktığı soruyu kaydedebilir."}]}},carry:{takeaway:"Başkalarının da zorlandığını görmek yalnız hissetmeni azaltabilir. Bu, şimdiki ihtiyacını ortadan kaldırmaz.",followUp:{questionId:"compassion-2-return",question:"Yanıtında hangi destek eksikti? Onu eklemek, sıradaki yararlı işini nasıl etkiledi?",observationPrompt:"Eksik desteği ve doğrudan gördüğün etkisini belirt; atladıysan veya etkisi belirsiz kaldıysa onu yaz.",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Tanım, üç kanıtlanmış etken demek değildir",paragraphs:["Neff’in tanımı kendine anlayış göstermeyi, ortak insan deneyimini ve acıyı fark ederek kabul etmeyi birleştirir. Bu adlar bir çerçeveyi anlatır. Geliştiricinin sayfası, her parçanın tek başına klinik iyileşmeye yol açtığını göstermez. Bütün özsaygıyı yarış olarak da tanımlamaz. Kişinin değeri performansa veya kıyasa bağlanabilir, ama bu bir örüntüdür; kavramın bütünü değildir. [C11: compassion-neff-definition] Kendi yanıtında hangi parçanın eksik olduğunu görmek, kendini başkalarından daha şefkatli veya daha yetersiz saymak için bir puanlama değildir.","Bu üç noktaya bakarak verdiğin yanıtı incele. Zor olanı kabul ettin mi? Yaşadığını yalnızca senin kusurlu olduğunun kanıtı saymaktan kaçındın mı? İşe yarayan bir yanıt sundun mu? Sıcak sözler yapay geliyorsa cümlen nötr ve saygılı olabilir. Önceki derste seçtiğin işi koru. Bu, ODA’nın kısa uygulamasıdır. Bildirebileceğin şey, o destekle yaptığın gerçek iştir. Tanı veya doğrulanmış bir parça puanı değildir. Bir soruya gerçekten bakıp bakmadığını söyleyebilirsin; duygunun ne kadar değiştiğini bunu yapmış olmanın şartı sayman gerekmez."]},{heading:"Günlük işi destekleyebilir, onun yerini almaz",paragraphs:["Geliştiricinin öz şefkat günlüğü, bir zorluğu fark etmeyi, başkalarının da benzer şeyler yaşadığını görmeyi ve anlayışlı sözler yazmayı ister. Bir hafta veya daha uzun süre, genellikle akşamları her gün yazmayı önerir. Bu rehber uygulamanın nasıl öğretildiğini belgeler. Tek başına klinik etki veya en iyi yazma süresini belirlemez. [C18: compassion-journal-guidance] Ders, aynı denemenin etrafında daha kısa, isteğe bağlı bir kontrol kullanır. Bu uyarlamayı, bütün programın etkisini veren uygulama gibi sunmak doğru olmaz.","Yalnızca yardım ediyorsa yaz. İçinden cevaplayabilir, iletişim desteği alabilir veya ayrıntıları başka yerde tutabilirsin. Düşünmek zihnindeki döngüyü besliyorsa saati değiştir ya da yazmayı bırak. Amaç soruya bakmak, hata düzeltmek veya destek istemekse günlük yazısı hazırlıktır. Kendi hazırlık kaydı olabilir; sonraki işin yapıldığının kanıtı değildir. Çalıştığın soruyu, düzelttiğin hatayı veya gönderdiğin talebi kaydet. Acil bildirimler ve yerleşik güvenlik işlemleri kişisel düşünme alıştırmasını beklememeli. Özel ayrıntıları paylaşmadan da hangi yararlı adımı attığını belirtme seçeneğin var."]}],sourceIds:["compassion-neff-definition","compassion-journal-guidance"]}},{schemaVersion:2,revision:2,id:"compassion-3",courseId:"compassion",locale:"tr",title:"Ara verdin, hâlâ üzgünsün. Şimdi ne yardımcı olur?",goal:"Aynı yararlı işten önce istersen destekleyici bir ara ver. Tamamlamak için rahatlamayı şart koşma.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ara verdin ama canın hâlâ acıyor. Şimdi kendine iyi bakmak için atabileceğin küçük adım ne?",reason:{id:"compassion-3-reason",label:"Sakinleşmeyi beklerken hangi iş yarım kalıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Yararlı geri bildirimle ilgilenmek","Yoğun sıkıntıda desteği seçmek","Sakinleşmeyi beklemeden işe dönmek"]},why:{id:"compassion-3-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-3-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Öz şefkat molasında zorlandığını kabul eder, başkalarının da zorlanabildiğini görür ve sana yardımcı olacak bir karşılık düşünürsün. Bu, geliştiricinin rehberidir. Deney iki dakikalık molayı değil, sekiz haftalık programı inceledi. Eksik kalan bir yıllık izlemde karşılaştırma grubu yoktu. Programdaki fayda, bu kısa aranın aynı etkiyi vereceğini göstermez.","Aynı gündelik aksamada “Bu zor; ne yardımcı olur?” de. Dokunmak, gözleri kapatmak, bedene odaklanmak ve sıcak duygu isteğe bağlı. Normal nefes al; tercih ediyorsan çevrene bak. Yararlı işinin küçük kısmını yap, uyarla veya destek iste. Sıkıntın artarsa dur. Ara, seçimine hazırlık olur. Gerçekte yaptığın işi ayrı kaydet; his değişmesini bekleme."],example:{title:"Emre’nin geri bildirime yanıtı",text:"Saat 15.00’te Emre, üzerinde çalıştığı taslak hakkında zor bir geri bildirim alıyor. Yalnızca sözle ara veriyor: “Bu zor; şimdi ne yardımcı olur?” Dokunmak rahatsız ettiği için atlıyor. Hâlâ üzgünken masasında belirtilen bir hatayı düzeltiyor. Düzeltmeyi kaydediyor. Taslak yeniden kontrol istiyor, duygusu da kaybolmadı. Emre, durumu bütünüyle çözdüğünü değil, o gün hangi hatayı düzelttiğini söylüyor."}},move:{invitation:"İşe yarıyorsa kendine destek olmak için kısa bir ara ver. Sonra başa çıkabileceğin aynı işi yapmayı, onu uyarlamayı veya destek almayı seç.",instructions:["Hafif, gündelik bir zorluk kullan. Hatırlamaya kendini zorlama.","Ortam uygunsa işe yarayan tek bir sonraki adımı at."],prompts:[],suggestions:{action:["Taslakta gerekli bir düzeltme yap","Seçtiğim bilgi güncellemesini gönder","Planladığım destek talebini ilet"],minimum:["Belirtilen bir hatayı düzelt","Bir güncelleme cümlesi gönder","Tek bir destek ihtiyacını belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Gündelik zor bir geri bildirimden sonra","Aynı aksamanın başladığı anda"],place:["Güvenli çalışma masamda","Sessiz ve tanıdık bir yerde"],minutes:[2,1,5],fallback:["Çevreme bak ve nötr sözler kullan","Dur ve işe yarayan destek iste"],observation:["Kendime destek olmak için attığım sonraki adım","Rahatsız olduğumda durup durmadığım"]},suggested:{action:"Taslakta gerekli bir düzeltme yap",minimum:"Belirtilen bir hatayı düzelt",minutes:2,cueHint:"Gündelik zor bir geri bildirimden sonra",placeHint:"Güvenli çalışma masamda",obstacleHint:"Aranın duyguyu yok etmesini bekliyorum.",fallbackHint:"Çevreme bak ve nötr sözler kullan",observationHint:"Kendime destek olmak için attığım sonraki adım"},stopRule:"Dokunmayı veya hatırlamayı atla. Sıkıntı hissedersen dur; gerektiğinde destek ara.",accessibleAlternative:"Gözlerin açık kalsın, normal nefes al, odaya dikkat et. Bedene odaklanmak veya sıcak duygu gerekmiyor."},result:{question:"Kendine destek olmak için seçtiğin sonraki adımı attın mı?",observationPrompt:"Harekete geçtin mi, uyarladın mı, durdun mu, destek mi istedin?"},judgment:{primary:{id:"compassion-3-upset-after-pause",scenario:"Emre geri bildirimden sonra rahat bir ara verdi. Hâlâ üzgün, ama taslaktaki açık bir hatayı güvenle iki dakikada düzeltebilir. Taslağın değerlendirileceği görüşmeye dört dakika var.",question:"Aranın amacına hangi seçim uyar?",bestOptionId:"manageable-correction",options:[{id:"pause-and-correct-later",text:"İki dakika daha ara versin; taslağı aceleye getirmemek için düzeltmeyi görüşmeden sonraki bir zamana planlasın.",feedback:"İş gücünü aşıyorsa daha çok zaman yardımcı olabilir. Bu güvenli düzeltme görüşmeden önceye sığıyor. Üzgünken mevcut küçük işi dene; yoğun sıkıntı gelirse durma seçeneğin var."},{id:"manageable-correction",text:"Üzgünken açık hatayı düzeltsin; bu adım yoğun sıkıntı vermeye başlarsa onun yerine destek almayı seçsin.",feedback:"Gereken sonuç rahatlama değil. Ara, gerektiğinde destek dahil, yapılabilir bir seçimi destekliyor. Emre duygusunun değiştiğini iddia etmeden gerçek düzeltmeyi kaydedebilir. Yaptığı iş ve hissettiği şey ayrı kalır."},{id:"review-broader-priorities",text:"Önce geri bildirimin genel önceliklerini değerlendirsin; belli olan hatayı sonraki taslak çalışmasında düzeltmeyi planlasın.",feedback:"Genel değerlendirme en önemli şeyi gösterebilir. Burada gerekli düzeltme zaten açık ve görüşmeden önceye sığıyor. Şimdi yap; daha geniş öncelikleri ayrı bir zamanda değerlendirebilirsin."}]}},carry:{takeaway:"Kendine özen gösterdiğin ara seçim yapmanı destekler. Hoş bir duygu üretmek zorunda değildir.",followUp:{questionId:"compassion-3-return",question:"Aradan sonra harekete mi geçtin, uyarladın mı, destek mi aradın, yoksa durman mı gerekti?",observationPrompt:"Gerçek sonraki adımı belirt. Arayı kullandın mı, atladın mı, onu da söyle.",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Mola ve program farklı şeyler",paragraphs:["Neff’in öz şefkat molası yönergeleri, incinmeyi fark etmeyi, zorlanmanın insan hayatının parçası olduğunu görmeyi ve anlayışlı sözler veya dilek sunmayı içerir. Özgün rehberde destekleyici dokunuş vardır. Yönergeler, molanın tek başına etkisini veya kanıtlanmış iki dakikalık süreyi belirlemez. [C16: compassion-break-guidance] Ders dokunmayı ve hatırlamayı isteğe bağlı tutar, sonrasına gerçek bir adım ekler. Bunlar ODA uyarlamalarıdır. Kısa arayı uygulayabilir veya atlayabilirsin; özgün programın bütününü yapmış sayılmazsın.","Bilinçli Farkındalık Temelli Öz Şefkat deneyi, toplumdan 52 yetişkini sekiz haftalık programa veya bekleme listesine rastgele ayırdı. Programda haftalık iki saatlik oturumlar, dört saatlik yoğun uygulama günü ve kayda değer günlük uygulama önerisi vardı. Kontrollü son ölçümlerde birkaç sonuç programı destekledi. Bir yıl sonra yalnızca 15 program katılımcısı yanıt verdi. Eşzamanlı kontrol grubu yoktu. Bu izlem herkes için kontrollü faydaların korunduğunu kanıtlayamaz. Deney molayı ayrı da sınamadı. [C05: compassion-mindful-self-compassion-rct] Küçük kişisel aranı değerlendirirken bütün programın etkisini ona yükleme."]},{heading:"Dokunmak ve rahatlamak ayrı seçenekler",paragraphs:["Dreisoerner ve çalışma arkadaşları sağlıklı genç yetişkinlerde, laboratuvar stresinden önce isteğe bağlı yatıştırıcı dokunuşu inceledi. Kortizol yanıtları farklıydı; bildirilen stres ve kalp hızı farklı değildi. Deney oksitosini ölçmedi, kalıcı klinik iyileşmeyi kanıtlamadı. Fizyolojik sonuç, daha iyi hissedeceğini vaat etmez. [C14: compassion-touch-trial] Buradaki gözler açık, dokunmasız, normal nefes seçenekleri erişim ve güvenlik içindir. Araştırılan dokunma protokolünün aynısı değildir. Bu ayrımı, ne denediğini ve ne olduğunu kaydederken de koru.","Uygulamanın tamamını sözle yapabilir, nötr sözler kullanabilir veya dışarıdaki bir şeye bakabilirsin. Başka biriyle temas gerekmiyor. Anı, dokunma veya içeriye odaklanma rahatsızlığı artırıyorsa sıcak duygu için zorlamak yerine dur. Basit destekleyici bir etkinlik veya insan yardımı seç. Sonraki iş düzeltme, destek isteği ya da dinlenme olabilir. O gerçek adımı kendi en küçük haliyle kaydet. Yarıda bırakılmış ara da bilgidir. Yeterince çabaladığını kanıtlamanı gerektirmez. Uygulamadaki hisle sonraki işi birbirinden ayırabilir, koşullarına uygun olanı seçebilirsin."]}],sourceIds:["compassion-break-guidance","compassion-mindful-self-compassion-rct","compassion-touch-trial"]}},{schemaVersion:2,revision:2,id:"compassion-4",courseId:"compassion",locale:"tr",title:"Bir saat daha mı? Dinlenmene de yer aç.",goal:"Gerçek riskleri kontrol et. Aynı denemede işe yarayan bir sınır veya destek adımı at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"İş yine akşama uzadı. Hangi gerçek riski ele almalısın? Seni biraz daha çalışmaya iten ne?",reason:{id:"compassion-4-reason",label:"Ek çalışma sana neye mal oluyor? Hangi gerçek risk sürüyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İş sonrası dinlenmeyi korumak","Sevdiklerime zaman ayırmak","Gerçek güvenlik ihtiyacıyla ilgilenmek"]},why:{id:"compassion-4-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-4-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Gilbert’in tehdit, başarma isteği ve yatışma modeli klinik bir çerçevedir. Beyindeki üç açma kapama düğmesi değildir. Daha çok başarmak gerçek ihtiyacı mı karşılıyor, yoksa döngüyü mü uzatıyor? Korunmak ve gerekli imkânları bulmak güvenliği etkileyebilir. İçini rahatlatan sözler onların yerini tutmaz.","Aynı aksamayı veya örüntüyü kullan. Fazla çalışmak tekrarlanıyorsa işi bitireceğin sınırı seçmeden gerçek tarihleri ve sonuçları kontrol et. Gerçek tehlike, somut yardım ister. Nefes ve canlandırma isteğe bağlı; çevrene bakarak ara vermek yeterli olabilir. Sakinlik, boş gelen kutusu veya onay şartı koymadan sınırı uygula ya da talebini ilet."],example:{title:"Ece işi bırakacağı saati belirliyor",text:"Saat 21.00’de Ece kayıtlarında yine geç saatlere kadar çalıştığını görüyor. Acil teslim tarihi yok. Masasında otururken lambaya bakıyor, yarının ilk işini belirtip iş uygulamalarını kapatıyor. Kaygı sürüyor. Planladığı dinlenme için masadan kalkıyor ve uyguladığı sınırı kaydediyor. Bitmemiş bir e-posta sabaha kalıyor. Her işi bitirdiğini değil, seçtiği saatte çalışmayı gerçekten bıraktığını söylüyor."}},move:{invitation:"Aynı örüntüde gerçek riski kontrol et. Uygulanabilir bir sınır koy veya işe yarayan destek iste.",instructions:["Sınır seçmeden teslim tarihlerini, güvenliği ve sorumlulukları kontrol et.","Tek bir sınırı uygula veya destek talebini ilet."],prompts:[],suggestions:{action:["Bırakma saatinde iş uygulamalarını kapat","Güvenliğim için somut bir yardım iste","İş için uygulanabilir bir sınır ilet"],minimum:["İş uygulamalarını kapat ve masadan kalk","Bir destek talebi ilet","İş için yapılabilir bir sınır söyle"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Seçtiğim işi bırakma saatinde","Aynı örüntü tekrarlandığında"],place:["Çalışma masamda","Güvenli bir destek kanalında"],minutes:[2,1,5],fallback:["Gerçek acil sorumluluğu netleştir","Sınırı güvenle uygulamak için yardım iste"],observation:["Sınırı gerçekten uygulayıp uygulamadığım","Hangi gerçek riskin ortaya çıktığı"]},suggested:{action:"Bırakma saatinde iş uygulamalarını kapat",minimum:"İş uygulamalarını kapat ve masadan kalk",minutes:2,cueHint:"Seçtiğim işi bırakma saatinde",placeHint:"Çalışma masamda",obstacleHint:"Kaygı kaybolana kadar çalışmayı sürdürüyorum.",fallbackHint:"Gerçek acil sorumluluğu netleştir",observationHint:"Sınırı gerçekten uygulayıp uygulamadığım"},stopRule:"Rahatsız ediyorsa nefese odaklanmayı veya canlandırmayı bırak. Gerçek tehlike, somut korunma ve destek gerektirir.",accessibleAlternative:"Oturarak, gözlerin açık, normal nefesle odaya dikkat et. Canlandırma veya sıcak duygu gerekmiyor."},result:{question:"Seçtiğin sınırı gerçekten uyguladın mı, destek talebini ilettin mi?",observationPrompt:"Hangi sınırı kullandın ve ardından gerçekte ne oldu?"},judgment:{primary:{id:"compassion-4-no-urgent-deadline",scenario:"Ece eleştirilmekten korktuğu için çalışmayı sürdürüyor. Teslim tarihlerini kontrol etti; acil iş kalmadı. Dinlenmesini korumak için işi bırakacağı saati seçti.",question:"Hangi adım bu sınırı sınar?",bestOptionId:"priority-and-close",options:[{id:"priority-and-close",text:"Yarının ilk işini not etsin; kaygısı sürse de seçtiği saatte iş uygulamalarını kapatıp çalışmayı bıraksın.",feedback:"Bu seçim tekrarlayan davranışla ilgilenirken yarının işini koruyor. Ece her e-postayı bitirmeden veya zorla sakinleşmeden yapılabilir bir sınırı deneyebilir. Gerçek acil risk varsa farklı bir yanıt gerekir."},{id:"finish-tomorrow-task",text:"Önemli işi hallettiğinin kanıtıyla durabilmek için yarının ilk önceliğini bu gece bitirmeye biraz daha zaman ayırsın.",feedback:"Bitirmek daha güvenli hissettirebilir. Ama bunu gerektiren acil teslim tarihi yok. Seçilen sınırın ele aldığı aynı döngüyü uzatıyor. Öncelik notunu koru ve kararlaştırılan saatte durmayı dene."},{id:"scan-before-closing",text:"Gözden kaçan teslim tarihi olup olmadığını kontrol etmek için beş dakika e-posta tarayıp uygulamaları sonra kapatsın.",feedback:"Aciliyet bilinmiyorsa son kontrol yararlı olabilir. Ece tarihleri zaten kontrol etti. Yeni tarama seçtiği sınırı geciktiriyor. Yarının önceliğini belirt ve uygulamaları kapat; gerçekten olanı kaydet."}]}},carry:{takeaway:"Gerçek riski kontrol et. Kendine özen göster: somut sınır koy, gereken imkânları ara veya destek iste.",followUp:{questionId:"compassion-4-return",question:"Sınırı sınadın mı? Yeni risk çıktı mı, çıkmadı mı, yoksa belirsiz mi kaldı?",observationPrompt:"Hangi zamanı veya imkânı korudun? Ardından gerçekten hangi sonuç ortaya çıktı?",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Klinik çerçeve, üç beyin düğmesi değil",paragraphs:["Gilbert’in klinik derlemesi tehdit, peşinden gitme veya başarma isteği ve bağ kurarak yatışmayı sade bir işlevsel çerçevede kullanır. Şefkat odaklı terapiyi ve uygulayıcı alıştırmalarını anlatır. Üç ayrı beyin devresini, tek nefes vermenin etkisini veya tehdit sistemini gerçekten kapatan düğmeyi gösteren deney değildir. [C07: compassion-gilbert-cft] Rahat nefes ve şefkatli canlandırma, hemen durma izniyle isteğe bağlı uygulamalar olabilir. Rahatsız ediyorsa devam etmen veya kendini gevşetmeye zorlaman gerekmez. Çerçeve bir durumu anlamak için kullanılabilir; kanıtlanmış fizyolojik açıklama olarak sunulamaz.","Model bir tehlikenin gerçek olup olmadığına da karar veremez. Barınma sorunu, yetersiz gelir, sağlık ihtiyacı veya güvenli olmayan ilişki, imkân ve somut değişiklik gerektirebilir. Korunmak ve gerekli imkânlar güvenliği etkileyebilir. Bu durumda fazladan çalışmanın gerçekte ne sağlayacağını kontrol et. Acil sorumluluk kalmadığında sınır yararlı bir deneme olabilir. Risk sürüyorsa kendine destek olmak için korunman veya yardım alman gerekebilir. Aynı denemenin kayıtları bu durumları ayırır. Öncelik notu işi kapatmaya hazırlıktır. İş uygulamalarını kapatıp masadan kalkmak ise o sınırı uygulamaktır. İkisini aynı iş gibi kaydetme."]},{heading:"Kazanan meditasyon yok, sıcak duygu şartı yok",paragraphs:["Zeng ve çalışma arkadaşları 1.759 katılımcılı, farklı tasarımlar içeren veriye dayanan 24 çalışmayı derledi. İlgili alt grup analizinde iyi dilek meditasyonu tahmini 0,424, şefkat meditasyonu tahmini 0,286’ydı. Alt gruplar arasında istatistiksel olarak anlamlı fark bulunmadı. Bu nedenle sayılar daha iyi uygulamayı belirlemiyor. Şefkatin etkisiz olduğunu da göstermiyor; ODA’nın yatışma alıştırmasına etki tahmini vermiyor. [C10: compassion-kindness-review] Birbirinden farklı uygulamaların sayısını karşılaştırırken, aradaki farkın belirsizliğini korumak gerekir. Ortalama etkiyi kendi kısa arana doğrudan aktaramazsın.","Geliştiricinin rehberi anlayışlı bir niyet ile hoş duygular hissetmeyi birbirinden ayırır; uygulama yoğun sıkıntı verirse geri çekilmeyi önerir. [C12: compassion-practice-safety] Sana uyuyorsa canlandırma yerine dışarıdaki bir şeye, sıradan etkinliğe veya desteğe yönel. Rahatsızlığı fizyolojik bir “backdraft” mekanizması veya yeni tanı diye adlandırma. Burada ölçülen, gerçekten uygulanan sınır veya iletilen somut taleptir. İş bittiğinde kaygın sürebilir, karşı taraf katılmayabilir. Bu gözlemler uygulamayı sıcak duygu şartına çevirmeden sıradaki biçimine yol gösterebilir. Sonuçları olduğu gibi kaydet; daha iyi hissetmediğin için gerçek adımını silme."]}],sourceIds:["compassion-gilbert-cft","compassion-kindness-review","compassion-practice-safety"]}},{schemaVersion:2,revision:2,id:"compassion-5",courseId:"compassion",locale:"tr",title:"Utandın mı? Sorumluluk gerçekten kimin?",goal:"Aynı aksamada gerçek sorumluluğunu kontrol et. Sonra uygun bir telafi, korunma veya destek adımı at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Borçlu olduğun telafiden mi kaçıyorsun, başkasının suçunu mu üstleniyorsun? Önce ne olduğuna bak.",reason:{id:"compassion-5-reason",label:"Sana ait olmayan sorumluluğu üstlenmek, neyi görmezden gelmene veya kabul etmene yol açar?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçekten verdiğim zararı telafi etmek","Haksız suçlamayı reddetmek","Güvenli destek istemek"]},why:{id:"compassion-5-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-5-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bütün benliğine yönelen utanç, sıklıkla saklanmayla veya savunmaya geçmeyle ilişkilidir. Davranışa odaklanan suçluluk, empati ve telafiyle ilişkili olabilir. Bunlar eğilimdir. Aşırı suçluluk zarar verebilir; zarar gördükten sonra utanç hissetmek yanlış yaptığını kanıtlamaz. Hissettiğin şey, sorumluluğun kimde olduğunu tek başına söylemez.","Aynı aksamada ne yaptığına, bunun zarar verip vermediğine bak. Gerçek zarar için ölçülü telafi, kötü muamele için korunma veya destek seç. Duygunu kendine özel adlandırıp beklentiyi kontrol edebilirsin. Paylaşmak isteğe bağlı; yalnızca güvenli ve dinlemeye istekli biriyle. Uygun bir adım at. Sözleri değiştirmek tek başına telafiyi tamamlamaz."],example:{title:"Can sorumluluğuna bakıyor",text:"Öğle molasında Can iş arkadaşına söylediği sert sözü yeniden değerlendiriyor. Kendine kötü insan demeden sözünü ve etkisini belirtiyor. Özel mesajla o söz için özür diliyor, verdiği yanlış bilgiyi düzeltiyor. İş arkadaşı o gün yanıt vermiyor. Can güvence veya af istemeden telafiyi kaydediyor. Karşı tarafın onu rahatlatması şartı koymuyor; yaptığı düzeltme ile yanıtı ayrı tutuyor."}},move:{invitation:"Aynı aksamada olanları kontrol et. Gerçek zarar için telafi; yoksa korunma veya destek seç.",instructions:["Özür seçmeden önce gerçek sorumluluğunu belirle.","Güvenli bir telafi, korunma veya destek adımı at."],prompts:[],suggestions:{action:["Olanlara uygun bir telafi yap","Güvenli bir destek talebi ilet","Kendimi koruyan bir sınırı uygula"],minimum:["Verdiğim bir zararı telafi et","Bir destek talebi ilet","Güvenli bir sınır söyle"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Gerçek sorumluluğumu kontrol ettikten sonra","Aynı aksamanın başladığı anda"],place:["Güvenli özel bir mesajlaşmada","Güvendiğim destek yerinde"],minutes:[2,1,5],fallback:["Güvensiz iletişimden önce destek ara","Paylaşmadan güvenli bir düzeltme yap"],observation:["Olanlar ve seçtiğim yol","Gerçekten yaptığım telafi veya korunma"]},suggested:{action:"Olanlara uygun bir telafi yap",minimum:"Verdiğim bir zararı telafi et",minutes:2,cueHint:"Gerçek sorumluluğumu kontrol ettikten sonra",placeHint:"Güvenli özel bir mesajlaşmada",obstacleHint:"Utancı zarar verdiğimin kanıtı sayıyorum.",fallbackHint:"Güvensiz iletişimden önce destek ara",observationHint:"Olanlar ve seçtiğim yol"},stopRule:"Sırf utandın diye özür dilemek, affetmek veya güvenli olmayan birine ulaşmak zorunda değilsin. Tehlikede korunmayı seç.",accessibleAlternative:"Düşüncelerini kendine sakla. Nötr sözler söyle, yaz, işaret dili kullan veya yardım iste. Paylaşmak ve bedenine odaklanmak isteğe bağlı."},result:{question:"Seçtiğin, duruma uygun adımı gerçekten attın mı?",observationPrompt:"Olanlar hangi sorumluluğu gösterdi ve onunla ilgili gerçekte ne yaptın?"},judgment:{primary:{id:"compassion-5-imposed-shame",scenario:"İrem doğru bir şey söyledikten sonra iş arkadaşı herkesin önünde onunla alay ediyor. İrem utanıyor. Olanlar onun hata yaptığını veya zarar verdiğini göstermiyor.",question:"Hangi sonraki adım uygun?",bestOptionId:"support-not-blame",options:[{id:"apologize-tension",text:"Gerilime katkıda bulunduğu için özür dilesin, böylece iş arkadaşına daha yapıcı karşılık verme fırsatı açsın.",feedback:"Telafi, gerçekten sorumlu olduğun zarara karşılık gelir. Bu durumda İrem’in sorumluluğu gösterilmiyor. Özür, olmayan suçu üstlenip alayı gözden kaçırır. Bunun yerine destek veya güvenli bir sınır düşün; doğrudan iletişim şart değil."},{id:"normalize-and-ignore",text:"Herkesin zor günler yaşadığını kendine hatırlatsın, çalışma ilişkisini korumak için bu olayı gündeme getirmeden bıraksın.",feedback:"Ortak insan deneyimi zarar veren davranışı mazur saymaz veya güvenlik kararını çözmez. İrem koşulları hesaba katarken uygun destek arayabilir. İş arkadaşıyla doğrudan yüzleşmesi gerekmiyor."},{id:"support-not-blame",text:"Utancı fark etsin, olanları açık tutsun; yanlış davranış uydurmadan güvenli destek veya bir sınır seçsin.",feedback:"Utanç, suçlu olduğunu göstermez. İrem olmayan hata için özür dilemeden, saygılı davranılmayı hak ettiğini kanıtlamadan alayla güvenli bir yoldan ilgilenebilir. Destek veya sınır bu duruma uygundur."}]}},carry:{takeaway:"Duygular özen ister. Sorumluluk kanıt ister. Telafi, korunma veya desteği buna göre seç.",followUp:{questionId:"compassion-5-return",question:"Olanlar telafi, korunma, işe yarayan destek veya daha fazla netlik mi gerektiriyordu?",observationPrompt:"Seçtiğin yolu ve gerçek adımı belirt. Kendine saklamak istediğin ayrıntıları paylaşman gerekmiyor.",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Utanç ve suçluluk, eğilimleri anlatır",paragraphs:["Tangney ve çalışma arkadaşları ahlaki duygu ve davranışları, çoğunlukla gözleme dayalı araştırmalardan derledi. Bütün benliğe yönelen utanç, sıklıkla geri çekilme veya savunmaya geçmeyle ilişkiliydi. Davranışa odaklanan suçluluk empati ve telafiyle ilişkili olabiliyordu. Bağlam ve ölçüm önemlidir. Derleme utancın her zaman yıkıcı veya suçluluğun her zaman yararlı olduğunu belirlemez. Aşırı ya da zihinde dönüp duran suçluluk da zararlı olabilir. [C08: compassion-tangney-moral-emotions] Bir his için genel örüntü anlatmak, senin durumunda kesin hüküm vermek değildir.","Utanç; istismar, dışlanma, ayrımcılık veya hastalık sonrasında, hisseden kişi yanlış yapmadan da gelebilir. Sırf telafi alıştırmasına uysun diye, utancından yola çıkıp yanlış bir şey yaptığın sonucuna varma. Önce gerçek davranışı ve sonuçlarını belirle. Verdiğin zararda ölçülü özür uygun olabilir; karşı tarafın seni rahatlatmasını veya affetmesini istemek gerekmez. Suç dayatılıyorsa destek ve korunma daha uygun olabilir. Cümleyi değiştirmek tek başına utançtan yararlı suçluluğa nedensel geçiş göstermez veya telafinin yapıldığını kanıtlamaz. Sonraki adımın neyi düzelttiğini veya koruduğunu, gerçekte yaptığın işe göre kaydet."]},{heading:"Güvenli paylaşım isteğe bağlı",paragraphs:["Brown, 215 kadınla görüşerek utançla baş etme kuramını geliştirdi. Utancı ve tetikleyicilerini fark etmek, beklentileri gerçeklikle karşılaştırmak, güvenli bağ bulmak ve utancı adlandırmak bu nitel araştırma ve uygulayıcı çerçevesindedir. Kaynak dört adımlı sıranın kontrollü tedavi deneyini doğrulamaz. Zorunlu paylaşımın sonuçları iyileştirdiğini de göstermez. [C09: compassion-brown-shame-resilience] Buradaki adımlar, kullanabileceğin yönler olarak kalır; hepsini sırayla tamamlamak veya birine anlatmak şartı değildir. Anlatma kararı güvenliği ve dinlemeye istekli kişiyi hesaba katmalı.","Sıradaki seçimine yarayan kısmı kullan. Travma hatırlamak, bedeni taramak veya hikâye anlatmak gerekmiyor. Güvenli ve istekli biri yardımcı olabilir, ama böyle biri bulunmayabilir. Özel düşünme, profesyonel destek talebi, bilgi düzeltmesi veya koruyucu sınır alternatiflerdir. Sana zarar veren ya da bilgiyi aleyhine kullanabilecek birine anlatma. Süren veya yoğun utanç uzman desteğini hak eder. Bu denemede bütün duyguları adlandırmana veya belirli sırayı tamamlamana bakmıyoruz. Hangi uygun işi yaptığın ve karşılığında ne olduğu önemli. Ayrıntıları kendine saklayabilirsin."]}],sourceIds:["compassion-tangney-moral-emotions","compassion-brown-shame-resilience"]}},{schemaVersion:2,revision:2,id:"compassion-6",courseId:"compassion",locale:"tr",title:"Anlayışlı bir not daha mı? Şimdi değişikliği yap.",goal:"Gerçek denemelere bakıp aynı uygulamayı toparla. Yapılabilir bir telafi, korunma veya destek adımı at.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Anlayışlı bir not yardımcı olabilir. Bu öğüdü dinlesen bugün hangi yararlı değişikliği yapardın?",reason:{id:"compassion-6-reason",label:"Yeni bir not hangi yararlı değişikliği erteler?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek telafiyi tamamlamak","Uygulanabilir bir sınırı korumak","Kendime yüklenmek yerine destek almak"]},why:{id:"compassion-6-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-6-cost",label:"Bu tekrarlayan durum sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Arkadaşın ağzından mektup, geliştiricinin önerisidir: ilgi ve değişim için öneriler sunar. On beş dakika, doğrulanmış en iyi süre değildir. Program deneyi mektubu ayrı sınamadı; bir yıllık izlemde karşılaştırma grubunu da korumadı. Bir mektup yazmakla o programın kanıtladığı sonuçları almak aynı şey değildir.","Aynı örüntünün kayıtlarına bak. Hangi yanıt telafiye, korunmaya, işe veya desteğe yol açtı? Yarayanı koru, bir engeli değiştir. İstersen notunda olanı, koşulları, özeni ve uygun adımı belirt. Uygunsa adımı yap; sonraki gerçekçi fırsatı planla. Sıcak duygu, af veya kusursuz seri gerekmiyor. Kayıtlı planı gerçek davranışla aynı sayma."],example:{title:"Derya’nın sonraki uygun adımı",text:"Pazar saat 19.00’da Derya, resmî yazıları ertelediği kayıtlarına bakıyor. Kısa ve gerçekçi not yardım etmiş; uzun öz eleştiri döngüsü etmemiş. Mutfak masasında dört anlayışlı cümle yazıyor, bir dosyalama hatasını düzeltiyor ve belirsiz bildirim için yardım istiyor. Büyük yığın hâlâ duruyor. İşe yarayan en küçük kısmı çarşambaya da koyuyor. Hemen rahatlayacağını veya her yazıyı bitireceğini vaat etmiyor."}},move:{invitation:"Aynı denemeye bak. Yardım edeni koru, tek engeli değiştir ve uygun bir sonraki adımı at.",instructions:["Gerçek denemeleri kullan. Eksik sonuçları belirsiz bırak.","Bir telafi, korunma, iş veya destek adımını gerçekten yap."],prompts:[],suggestions:{action:["Sıradaki işimdeki hatayı düzelt","Denediğim koruyucu sınırı kullan","Belirli destek talebimi gönder"],minimum:["Gerçek bir hatayı düzelt","Uygulanabilir bir sınır söyle","Belirli bir talep ilet"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Gerçek denemelerime baktıktan sonra","İşe yaradığını gördüğüm başlama anı tekrar geldiğinde"],place:["Mutfak masamda","Güvenli destek kanalımda"],minutes:[3,2,5],fallback:["Engel için yardım iste","Adımı küçült veya bilerek ara ver"],observation:["Attığım adım ve aldığım destek","Neyi koruduğum veya değiştirdiğim"]},suggested:{action:"Sıradaki işimdeki hatayı düzelt",minimum:"Gerçek bir hatayı düzelt",minutes:3,cueHint:"Gerçek denemelerime baktıktan sonra",placeHint:"Mutfak masamda",obstacleHint:"Rahatlatan sözler yazmak, yararlı değişikliğin yerini alıyor.",fallbackHint:"Engel için yardım iste",observationHint:"Attığım adım ve aldığım destek"},stopRule:"Sıkıntı hissedersen acı veren hatırlamayı veya yazmayı bırak. Telafi gerçek sorumluluk gerektirir; korunmak daha uygun olabilir.",accessibleAlternative:"Mektup isteğe bağlı. Dört nötr cümleyi içinden söyle, yaz, işaret dili kullan veya yardım iste. Sıcak duygu gerekmiyor."},result:{question:"Seçtiğin somut adımı o fırsatta gerçekten attın mı?",observationPrompt:"Neyi korudun, değiştirdin veya istedin? Sonrasında gerçekte ne oldu?"},judgment:{primary:{id:"compassion-6-boundary-after-review",scenario:"Derya bütçesini kontrol etti: borç vermek bu haftanın temel ihtiyaçları için gereken parayı kullanacak. Bekleyen talep yok. Bugün kimseyle iletişim kurmadan bu parayı kenara ayırabilir.",question:"Değerlendirme hangi işe yol açmalı?",bestOptionId:"reserve-essential-funds",options:[{id:"draft-future-refusal",text:"Sıradaki talep için anlayışlı ama açık bir ret yazsın; bugünkü parayı o zamana kadar kullanılabilir tutsun.",feedback:"Ret taslağı sonraki sınır için yararlı hazırlıktır. Bugün temel ihtiyaç parasını borç vermeye açık bırakır. Şimdi kenara ayır; sonradan kuracağın iletişimi ayrı davranış olarak kaydet."},{id:"reserve-essential-funds",text:"Bugün temel ihtiyaçlar için gereken miktarı kenara ayırsın, gelecekteki talepler için güvenli bir sınır hazırlasın.",feedback:"Parayı kenara ayırmak bugün borç vermeye açık miktarı değiştirir. Sınırı yazmak veya mesajın provasını yapmak tek başına hazırlıktır. Hemen iletişim kurmak veya daha iyi hissetmek şart değil."},{id:"budget-and-support",text:"Borç vermede hangi sınırı uygulayacağına karar vermeden önce bütçesini güvendiği bir destek kişisiyle yeniden gözden geçirsin.",feedback:"Bütçe veya güvenlik belirsizse destek yardımcı olabilir. Derya temel ihtiyaçların etkileneceğini zaten biliyor; bugün parayı güvenle ayırabilir. Gelecekteki talepler için sonrasında yardım isteyebilir."}]}},carry:{takeaway:"Kendine özen gösterirken olanları dürüstçe değerlendir. Sonraki adımını hayatına uydurmak için denemelerinin kayıtlarına bak.",followUp:{questionId:"compassion-6-return",question:"Sonraki denemede hangi somut yolu gerçekten seçtin? Hangi koşulu yeniden kullanmak işe yarar?",observationPrompt:"Gerçekte hangi adımı attığını belirt. Yazılı sınırı, gerçekten kullanana kadar hazırlık olarak tut.",adjustmentPrompt:"Sıradaki denemenin hayatına uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"İsteğe bağlı mektup gerçek seçimi destekler",paragraphs:["Neff’in arkadaşın ağzından mektup rehberi, güçlü ve zayıf yanlarını, koşullarını bilen ve sana değer veren birinin nasıl yanıt vereceğini düşünmeni ister. Değişim için anlayışlı öneriler ve mektubu sonradan okumak üzere kenara koymak vardır. Sayfa bir alıştırmayı belgeler. Tek başına etki deneyi veya doğrulanmış on beş dakikalık süre değildir. [C17: compassion-letter-guidance] Bu dersin dört cümle seçeneği ve gerçek sonraki adımı ODA uyarlamalarıdır. Daha kısa biçimi kullanmak, özgün programın bütün uygulamalarını yaptığın anlamına gelmez. Mektubu yazıp yazmamak senin seçimin.","Yazacaksan gündelik, başa çıkabileceğin bir aksama seç. Yetersiz gördüğün yanlarını listelemek, acı hikâyesi, koşulsuz sıcak duygu veya hazır bir arkadaş gerekmiyor. Nötr saygı yeterli olabilir: olanı ve ilgili koşulları anlat; kendine nasıl destek olabileceğini ve sonraki uygun adımı belirt. Telafi gerçek sorumluluğa aittir; sınır veya güvenlik gereken yerde korunmak uygundur. Tamamlanmış mektup hazırlık olarak kaydedilebilir. Somut düzeltmenin veya destek talebinin ayrı en küçük adımı vardır. Yazılmış borç verme sınırı, para gerçekten ayrılana veya güvenli fırsatta sınır kullanılana kadar hazırlık kalır. Yazılı öğüdü yapılmış değişikliğe çevirmeden önce ne yaptığını kontrol et."]},{heading:"Gelecek haftaya kayıtların yol gösterir",paragraphs:["Neff’in teselli eden ve koruyan şefkat dili uygulayıcı bakışlarını anlatır: rahatlatma ve kabulün yanında korunma, sınırlar ve hedefe yönelme. Bağımsız biçimde kanıtlanmış beyin sistemleri değildir. [C11: compassion-neff-definition] Bu dili yalnızca gerçek örüntüne bakmana yardım ediyorsa kullan. Gerekli değişikliği erteleyen rahatlatıcı not da gücünü hesaba katmayan sert plan da düzenleme isteyebilir. Hangisinin işe yaradığını görmek için, kendine ne söylediğine olduğu kadar sonra ne yaptığına da bak. Sözü davranışın yerine koyma.","Bilinçli Farkındalık Temelli Öz Şefkat çalışması, sekiz haftalık programı bekleme listesiyle karşılaştırdı. Eksik bir yıllık izlemde eşzamanlı kontrol yoktu. Kalıcı mektup etkisini belirlemez. [C05: compassion-mindful-self-compassion-rct] Bu yüzden son ders gerçekten bildirdiğin denemelere bakar. Yararlı bir yanıtı koru, tek engeli değiştir ve sıradaki fırsatın tarihini belirle. Yeni ritüel eklemek veya arayı telafi etmek gerekmiyor. Bu durum için hâlâ imkâna, yardıma veya uzman desteğine ihtiyacın varsa dürüstçe belirt. Kursu bitirmek telafiyi, rahatlamayı veya uygulamayı kanıtlamaz. Sıradaki kayıt gerçekte ne olduğunu göstersin. Sonucu bilmiyorsan belirsiz bırak; başarısızlık diye yorumlama."]}],sourceIds:["compassion-letter-guidance","compassion-neff-definition","compassion-mindful-self-compassion-rct"]}}],d=[{id:"compassion-1",practice:["Olanı belirt. Değerin hakkında hüküm verme.","Gerçekçi yeni teslim tarihini gönder","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1474418397713-7ede21d49118",alt:"Kayada oturup dağların üstünde gün doğumunu izleyen biri"}},{id:"compassion-2",practice:["Zorluğu abartmadan veya geçiştirmeden kabul et.","Yanlış çözdüğüm bir deneme sorusuna yeniden bak","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1529156069898-49953e39b3ac",alt:"Arkadan görülen, kol kola oturan arkadaşlar"}},{id:"compassion-3",practice:["Hafif, gündelik bir zorluk kullan. Hatırlamaya kendini zorlama.","Taslakta gerekli bir düzeltme yap","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1499209974431-9dddcece7f88",alt:"Batan güneşe doğru kollarını açan biri"}},{id:"compassion-4",practice:["Sınır seçmeden teslim tarihlerini, güvenliği ve sorumlulukları kontrol et.","Bırakma saatinde iş uygulamalarını kapat","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1441974231531-c6227db76b6e",alt:"Sakin ormana süzülen güneş ışığı"}},{id:"compassion-5",practice:["Özür seçmeden önce gerçek sorumluluğunu belirle.","Olanlara uygun bir telafi yap","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1544027993-37dbfe43562a",alt:"Birbirine uzanan iki el"}},{id:"compassion-6",practice:["Gerçek denemeleri kullan. Eksik sonuçları belirsiz bırak.","Sıradaki işimdeki hatayı düzelt","Gerçekte ne olduğunu kaydet ve sonraki uygun denemeyi seç."],correct:0,photo:{id:"1455390582262-044cdead277a",alt:"Deftere kalemle yazan bir el"}}];function k(a,t){const r=d[t],e=a.judgment.primary,n=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==n.id).map(i=>i.text);return l.splice(r.correct,0,n.text),{...r,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l,feedback:n.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}}const y={id:"compassion",title:"Hata mı yaptın? Kendine yüklenmeden düzelt.",subtitle:"6 ders. Sıcak duygu şartı koymadan aynı aksamada telafi, korunma veya desteğe ilerle.",description:"Küçümsemeyi bırakırken beklentiyi ve gerçekleri koru. Aynı denemede kendine nasıl destek olacağını seç, sorumluluğa bak ve sonraki uygun adımı at.",scope:"Hata, aksama veya acı veren anlar sonrasında kendine yüklenen yetişkinler için. Bu eğitim ve kişisel uygulamadır, terapi değildir. Travma, istismar veya süren ya da yoğun utanç yaşıyorsan lütfen bir uzmanla çalış. Öz şefkat alıştırmaları bazen eski acıları ortaya çıkarabilir. Krizdeysen veya kendine zarar vermeyi düşünüyorsan hemen bulunduğun yerdeki acil yardım numarasını ara.",outcome:"Tekrarlayan aksamaya adil bir yanıt, uygun telafi veya korunma ve yapılabilir bir sonraki deneme.",photo:{id:"1470252649378-9c29740c9fa8",alt:"Akşamın sıcak ışığında sessiz bir kır"},lang:"tr",lessons:s.map(k)};export{y as COURSE,s as LESSONS_V2,m as SOURCES};
